$flags = @("--version","--model-dir","--device","--npu-platform","--gpu-model-dir","--port","--ollama-port","--max-dim","--embed-model-dir","--embed-device","--embed-name","--embed-max-length","--embed-batch-size","--embed-threads","--whisper-dir","--whisper-device","--whisper-min-spread","--idle-timeout","--gpu-keepalive","--log-file","--debug","--vscode-compat","--vscode-ollama-version","--no-prompt-cache","--ignore-ir-version","--gpu-large-alloc","--cache-size-gb","--prewarm","--no-prewarm","--think-in-content","--tool-template","--offload-ratio","--scan","--backend")
$files = @("docs/API.md","README.md")
foreach ($f in $flags) {
  $hits = @()
  foreach ($file in $files) {
    $m = Select-String -Path $file -Pattern [regex]::Escape($f) -AllMatches
    if ($m) { $hits += "$file:$($m.Count)" }
  }
  $status = if ($hits.Count -eq 0) { "NOT FOUND" } else { ($hits -join ", ") }
  Write-Output "$f  =>  $status"
}

